using Atm;
sealed class Rec(NoteCounts s, Denomination? j, int failPass, bool failLoad) : IMoneyDispenser {
  public NoteCounts Stock { get; private set; } = s; public Denomination? Jammed => j;
  public List<string> Log = []; int n;
  public bool Dispense(NoteCounts x){ Log.Add("D"+x); if(++n==failPass) return false; Stock-=x; return true; }
  public bool Load(NoteCounts x){ Log.Add("L"+x); if(failLoad) return false; Stock+=x; return true; }
}
static class P { static void Main(){
  long cases=0, diffs=0;
  Denomination?[] jams=[null,Denomination.Fifty,Denomination.Twenty,Denomination.Ten];
  AccountState[] accts=[new(0,0),new(55,150),new(250,0),new(1000,0),new(-5,-10),new(250,200)];
  var ops=new List<Operation>();
  for(int a=-20;a<=260;a+=5) ops.Add(new Operation.Withdraw(a));
  for(int f=-1;f<=2;f++)for(int t=-1;t<=2;t++)for(int d=-1;d<=2;d++) ops.Add(new Operation.Deposit(new(f,t,d)));
  for(int f=-1;f<=7;f++)for(int t=-1;t<=7;t++)for(int d=-1;d<=7;d++)
  foreach(var j in jams) foreach(var ac in accts) foreach(var op in ops) foreach(var fp in new[]{0,1,2,3}) foreach(var fl in new[]{false,true}){
    var s=new NoteCounts(f,t,d);
    var d1=new Rec(s,j,fp,fl); var d2=new Rec(s,j,fp,fl);
    var r1=new OldCashMachine(d1).Execute(ac,op); var r2=new CashMachine(d2).Execute(ac,op);
    cases++;
    if(r1!=r2 || !d1.Log.SequenceEqual(d2.Log) || d1.Stock!=d2.Stock){ if(diffs++<5) Console.WriteLine($"{s} {j} {ac} {op} {fp} {fl}: {r1} vs {r2}"); }
  }
  Console.WriteLine($"cases={cases} diffs={diffs}");
}}
EOF
